package com.payflow;
import com.payflow.auth.*;import com.payflow.common.ApiException;import com.payflow.ledger.*;import com.payflow.transaction.*;import com.payflow.user.*;import com.payflow.wallet.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;
import java.util.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true) @SpringBootTest(properties={"payflow.jwt-secret=test-secret-that-is-long-enough-for-hmac-signing","spring.task.scheduling.enabled=false"})
class TransactionEngineIT {
  @Container static PostgreSQLContainer<?> pg=new PostgreSQLContainer<>("postgres:17-alpine");
  @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",pg::getJdbcUrl);r.add("spring.datasource.username",pg::getUsername);r.add("spring.datasource.password",pg::getPassword);}
  @Autowired AuthService auth;@Autowired UserRepository users;@Autowired WalletRepository wallets;@Autowired TransactionEngine engine;@Autowired TransactionRepository txs;@Autowired LedgerRepository ledger;
  int sequence;
  User user(String name){String s=name.toLowerCase()+sequence++;auth.register(new AuthController.RegisterRequest(name,s+"@test.local","98765"+String.format("%05d",sequence),"Password1!"));return users.findByEmail(s+"@test.local").orElseThrow();}
  @Test void normalTransferIsAtomicAndBalanced(){User a=user("Alice"),b=user("Bob");engine.topup(a,100_000,"topup-key-a");long before=txs.count();var result=engine.transfer(a,wallets.findByOwnerId(b.getId()).orElseThrow().getId(),30_000,"test","transfer-key-a");assertEquals(70_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());assertEquals(30_000,wallets.findByOwnerId(b.getId()).orElseThrow().getBalancePaise());assertEquals(before+1,txs.count());assertEquals(2,ledger.countByTransactionId(txs.findByReference(result.reference()).orElseThrow().getId()));}
  @Test void concurrentDoubleSpendAllowsOnlyOneDebit()throws Exception{User a=user("Sender"),b=user("One"),c=user("Two");engine.topup(a,100_000,"fund-sender");var pool=Executors.newFixedThreadPool(2);var gate=new CyclicBarrier(2);List<Future<Boolean>> f=new ArrayList<>();for(var x:List.of(b,c))f.add(pool.submit(()->{gate.await();try{engine.transfer(a,wallets.findByOwnerId(x.getId()).orElseThrow().getId(),80_000,null,UUID.randomUUID().toString());return true;}catch(ApiException e){assertEquals("INSUFFICIENT_BALANCE",e.code());return false;}}));assertEquals(1,f.stream().filter(v->{try{return v.get();}catch(Exception e){throw new RuntimeException(e);}}).count());assertEquals(20_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());pool.shutdown();}
  @Test void concurrentDuplicatesCommitOnce()throws Exception{User a=user("IdemSender"),b=user("IdemReceiver");engine.topup(a,100_000,"idem-fund");Long target=wallets.findByOwnerId(b.getId()).orElseThrow().getId();var pool=Executors.newFixedThreadPool(10);var gate=new CountDownLatch(1);List<Future<UUID>> futures=new ArrayList<>();for(int i=0;i<10;i++)futures.add(pool.submit(()->{gate.await();return engine.transfer(a,target,20_000,"same","same-payment-key").reference();}));gate.countDown();Set<UUID> refs=new HashSet<>();for(var f:futures)refs.add(f.get(20,TimeUnit.SECONDS));assertEquals(1,refs.size());assertEquals(80_000,wallets.findByOwnerId(a.getId()).orElseThrow().getBalancePaise());assertEquals(20_000,wallets.findByOwnerId(b.getId()).orElseThrow().getBalancePaise());pool.shutdown();}
  @Test void conflictingPayloadIsRejected(){User a=user("ConflictSender"),b=user("ConflictReceiver");engine.topup(a,100_000,"conflict-fund");Long target=wallets.findByOwnerId(b.getId()).orElseThrow().getId();engine.transfer(a,target,10_000,null,"conflicting-key");ApiException e=assertThrows(ApiException.class,()->engine.transfer(a,target,20_000,null,"conflicting-key"));assertEquals("IDEMPOTENCY_CONFLICT",e.code());}
}

